package com.bank.core;

import java.io.*;

// Correct persistence: native serialization writes to a BINARY byte sink, never a text file.
public class BinaryStore {

    public byte[] toBytes(Account account) throws IOException {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(buffer)) {
            oos.writeObject(account); // writes raw bytes, full range 0..255
        }
        return buffer.toByteArray();
    }

    public Account fromBytes(byte[] bytes) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois =
                 new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            return (Account) ois.readObject();
        }
    }
}
