package com.bank.core;

// Human-readable, auditable alternative. Real code uses Jackson; this shows the IDEA.
// Note: sessionToken is deliberately NOT written — sensitive data stays out of text.
public class JsonLikeWriter {

    public String toJson(Account a) {
        return "{"
             + "\"accountId\":\"" + a.getAccountId() + "\","
             + "\"holderName\":\"" + a.getHolderName() + "\","
             + "\"balance\":\"" + a.getBalance().toPlainString() + "\""
             + "}";
    }
}
