package com.bank.core;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.logging.*;

public class SerializationTargetDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar",
                                     new BigDecimal("1000000.00"), "live-session-xyz");
        BinaryStore store = new BinaryStore();

        byte[] bytes = store.toBytes(rajesh);
        log.info(() -> "Serialized binary length = " + bytes.length + " bytes");

        // WRONG: route the binary bytes through text — corrupts them.
        String asText = new String(bytes, StandardCharsets.UTF_8);
        byte[] back = asText.getBytes(StandardCharsets.UTF_8);
        boolean identical = Arrays.equals(bytes, back);
        log.warning(() -> "After text round-trip, bytes identical? " + identical);

        // RIGHT (machine): binary bytes reload perfectly.
        Account reloaded = store.fromBytes(bytes);
        log.info(() -> "Reloaded from binary: " + reloaded.getAccountId()
                        + " balance=" + reloaded.getBalance());

        // RIGHT (human): readable JSON for audit, without the sensitive token.
        String json = new JsonLikeWriter().toJson(rajesh);
        log.info(() -> "Audit-readable JSON = " + json);
    }
}
